{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C21"],
      "claim": "Uridine, a close ribonucleoside analogue (Morgan 0.339), has absolute oral bioavailability of only 5.8–9.9% in humans at oral doses of 8–12 g/m2, below the 20% threshold; the query shares the ribose and highly polar pyrimidine-dione character, supporting low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "Levovirin, a polar ribonucleoside with very low Caco-2 permeability, has human oral bioavailability <10%; this directly supports low F for the similarly polar, H-bond-rich query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "NHC, a ribofuranosyl heterocycle, is reported to have poor human bioavailability, reinforcing that polar ribonucleosides without strong transporter uptake tend to fall below 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "OGT719 (5-fluorouridine), the closest analogue (Morgan 0.344), has oral bioavailability ~25%, slightly above threshold; however, its uracil base has fewer H-bond donors and lacks the acidic ionization of the query, so this contradictory evidence has limited transferability.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C40"],
      "claim": "Ribavirin, a polar D-ribonucleoside, has oral bioavailability ~50% in patients, showing that transporter-mediated absorption can overcome polarity; however, the query lacks ribavirin's carboxamide and has an acidic xanthine-like base, so this high-F evidence transfers poorly.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is an extremely polar ribonucleoside with high H-bond donor count and acidic ionization, predicting poor passive permeability. The closest polar ribonucleoside analogues (uridine, levovirin) have human oral bioavailability below 20%, while the closest analogue with F~25% (OGT719) is less polar and does not outweigh the low-F evidence. Therefore, F is predicted to be <20%.",
  "evidence_gaps": [
    "No direct oral bioavailability data for the query molecule.",
    "No experimental data on nucleoside transporter affinity for the query's unusual N-aminoriboside linkage.",
    "Human PK data for xanthine-like ribonucleosides are lacking.",
    "The exact structural class and in vivo ionization behavior are uncertain."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

